116	func promptStartRestoredAgent(ctx context.Context, sessions []strategy.RestoredSession) (bool, error) {
117		startAgent := true
118		form := NewAccessibleForm(
119			huh.NewGroup(
120				newStartRestoredAgentConfirm(&startAgent, restoredSessionsCheckpointID(sessions)),
121			),
122		)
123		if err := form.RunWithContext(ctx); err != nil {
124			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
125				return false, nil
126			}
127			return false, fmt.Errorf("failed to choose resume action: %w", err)
128		}
129		return startAgent, nil
130	}
