145	func restoredSessionsCheckpointID(sessions []strategy.RestoredSession) string {
146		var checkpointID string
147		for _, session := range sessions {
148			current := strings.TrimSpace(session.CheckpointID)
149			if current == "" {
150				return ""
151			}
152			if checkpointID == "" {
153				checkpointID = current
154				continue
155			}
156			if checkpointID != current {
157				return ""
158			}
159		}
160		return checkpointID
161	}
